127	// sourceFile is a parsed production file and the names it uses for the
128	// packages it imports.
129	type sourceFile struct {
130		rel       string
131		dir       string
132		ast       *ast.File
133		qualifier string            // see agentImportName
134		imports   map[string]string // local package name to directory, for repository packages
135	}
136	
137	func newSourceFile(rel string, file *ast.File) *sourceFile {
138		f := &sourceFile{
139			rel:       rel,
140			dir:       path.Dir(rel),
141			ast:       file,
142			qualifier: agentImportName(file, rel),
143			imports:   map[string]string{},
144		}
145		for _, imp := range file.Imports {
146			dir, ok := strings.CutPrefix(strings.Trim(imp.Path.Value, `"`), modulePath+"/")
147			if !ok {
148				continue
149			}
150			// Without an alias the package name is assumed to match its directory,
151			// which holds for the repository's packages.
152			name := path.Base(dir)
153			if imp.Name != nil {
154				name = imp.Name.Name
155			}
156			f.imports[name] = dir
157		}
158		return f
159	}
