161	// typeDecl is a named type declared in a scanned file.
162	type typeDecl struct {
163		typ  ast.Expr
164		file *sourceFile
165	}
166	
167	// assertionResolver follows an asserted type to the package-agent capability
168	// it reaches, if any.
169	type assertionResolver struct {
170		interfaces map[string]*ast.InterfaceType // package agent's interfaces
171		methods    map[string]string             // see capabilityMethods
172		// decls holds every named type by directory and name. A name can have
173		// several declarations when build-tagged files declare it differently.
174		decls map[string]map[string][]typeDecl
175	}
176	
177	func (r *assertionResolver) addDecls(file *sourceFile) {
178		for _, decl := range file.ast.Decls {
179			gen, ok := decl.(*ast.GenDecl)
180			if !ok || gen.Tok != token.TYPE {
181				continue
182			}
183			for _, spec := range gen.Specs {
184				typeSpec, ok := spec.(*ast.TypeSpec)
185				if !ok {
186					continue
187				}
188				if r.decls[file.dir] == nil {
189					r.decls[file.dir] = map[string][]typeDecl{}
190				}
191				name := typeSpec.Name.Name
192				r.decls[file.dir][name] = append(r.decls[file.dir][name], typeDecl{typeSpec.Type, file})
193			}
194		}
195	}
196	
197	// reach reports the capability typ, as written in file, reaches: by naming a
198	// package-agent capability interface, declaring one of its methods, or naming
199	// or embedding a type that does. via describes the step that reached it.
200	func (r *assertionResolver) reach(typ ast.Expr, file *sourceFile, seen map[ast.Expr]bool) (string, string, bool) {
201		if seen[typ] {
202			return "", "", false
203		}
204		seen[typ] = true
205		if name, ok := agentInterfaceName(typ, file.qualifier, r.interfaces); ok {
206			if _, allowed := nonCapabilityInterfaces[name]; allowed {
207				return "", "", false
208			}
209			return name, "agent." + name, true
210		}
211		switch t := typ.(type) {
212		case *ast.ParenExpr:
213			return r.reach(t.X, file, seen)
214		case *ast.InterfaceType:
215			for _, field := range t.Methods.List {
216				for _, name := range field.Names {
217					if capability, ok := r.methods[name.Name]; ok {
218						return capability, "method " + name.Name, true
219					}
220				}
221				if len(field.Names) == 0 {
222					if capability, via, ok := r.reach(field.Type, file, seen); ok {
223						return capability, via, true
224					}
225				}
226			}
227		case *ast.Ident:
228			return r.reachDecls(file.dir, t.Name, seen)
229		case *ast.SelectorExpr:
230			if pkg, ok := t.X.(*ast.Ident); ok {
231				if dir, ok := file.imports[pkg.Name]; ok {
232					return r.reachDecls(dir, t.Sel.Name, seen)
233				}
234			}
235		}
236		return "", "", false
237	}
238	
239	func (r *assertionResolver) reachDecls(dir, name string, seen map[ast.Expr]bool) (string, string, bool) {
240		for _, decl := range r.decls[dir][name] {
241			if capability, via, ok := r.reach(decl.typ, decl.file, seen); ok {
242				return capability, via, true
243			}
244		}
245		return "", "", false
246	}
