259	// capabilityMethods maps each method declared by a capability interface to
260	// that interface, the alphabetically first when several declare it. Methods
261	// also declared by a non-capability interface (the Agent contract every agent
262	// implements) are left out, since asserting to them reaches no optional
263	// capability.
264	func capabilityMethods(interfaces map[string]*ast.InterfaceType) map[string]string {
265		shared := map[string]struct{}{}
266		for name := range nonCapabilityInterfaces {
267			if iface, ok := interfaces[name]; ok {
268				for _, method := range methodNames(iface) {
269					shared[method] = struct{}{}
270				}
271			}
272		}
273		methods := map[string]string{}
274		for _, name := range slices.Sorted(maps.Keys(interfaces)) {
275			if _, ok := nonCapabilityInterfaces[name]; ok {
276				continue
277			}
278			for _, method := range methodNames(interfaces[name]) {
279				_, isShared := shared[method]
280				_, taken := methods[method]
281				if !isShared && !taken {
282					methods[method] = name
283				}
284			}
285		}
286		return methods
287	}
288	
289	// methodNames returns the methods iface declares itself, not those it embeds.
290	func methodNames(iface *ast.InterfaceType) []string {
291		var names []string
292		for _, field := range iface.Methods.List {
293			for _, name := range field.Names {
294				names = append(names, name.Name)
295			}
296		}
297		return names
298	}
299	
300	// declaredInterfaces returns the interface types file declares, by name.
301	func declaredInterfaces(file *ast.File) map[string]*ast.InterfaceType {
302		interfaces := map[string]*ast.InterfaceType{}
303		for _, decl := range file.Decls {
304			gen, ok := decl.(*ast.GenDecl)
305			if !ok || gen.Tok != token.TYPE {
306				continue
307			}
308			for _, spec := range gen.Specs {
309				typeSpec, ok := spec.(*ast.TypeSpec)
310				if !ok {
311					continue
312				}
313				if iface, ok := typeSpec.Type.(*ast.InterfaceType); ok {
314					interfaces[typeSpec.Name.Name] = iface
315				}
316			}
317		}
318		return interfaces
319	}
320	
321	// agentImportName returns the identifier file uses to qualify package agent's
322	// names: the import's alias, or "agent" when it is imported plainly. Inside
323	// package agent itself the names are unqualified, reported as "". Files that do
324	// not import the package cannot assert to its interfaces at all; "-" matches
325	// nothing. rel is slash-separated, as git prints it.
326	func agentImportName(file *ast.File, rel string) string {
327		if path.Dir(rel) == agentPackageDir {
328			return ""
329		}
330		for _, imp := range file.Imports {
331			if strings.Trim(imp.Path.Value, `"`) != agentImportPath {
332				continue
333			}
334			if imp.Name == nil {
335				return "agent"
336			}
337			if imp.Name.Name == "." {
338				return ""
339			}
340			return imp.Name.Name
341		}
342		return "-"
343	}
344	
345	// agentInterfaceName reports which package-agent interface expr names, if any:
346	// qualifier.X for files that import the package, or a bare X where qualifier
347	// is "" (package agent and dot imports).
348	func agentInterfaceName(expr ast.Expr, qualifier string, interfaces map[string]*ast.InterfaceType) (string, bool) {
349		var name string
350		switch e := expr.(type) {
351		case *ast.SelectorExpr:
352			pkg, ok := e.X.(*ast.Ident)
353			if !ok || pkg.Name != qualifier {
354				return "", false
355			}
356			name = e.Sel.Name
357		case *ast.Ident:
358			if qualifier != "" {
359				return "", false
360			}
361			name = e.Name
362		default:
363			return "", false
364		}
365		_, ok := interfaces[name]
366		return name, ok
367	}
368	
369	// assertedTypes returns every type expression file asserts a value to: the
370	// X in v.(X) and in each case of a switch v.(type).
371	func assertedTypes(file *ast.File) []ast.Expr {
372		var types []ast.Expr
373		ast.Inspect(file, func(n ast.Node) bool {
374			switch n := n.(type) {
375			case *ast.TypeAssertExpr:
376				if n.Type != nil {
377					types = append(types, n.Type)
378				}
379			case *ast.TypeSwitchStmt:
380				for _, stmt := range n.Body.List {
381					if clause, ok := stmt.(*ast.CaseClause); ok {
382						types = append(types, clause.List...)
383					}
384				}
385			}
386			return true
387		})
388		return types
389	}
