391	// productionGoFiles lists the repository's tracked and untracked Go files
392	// outside _test.go, slash-separated relative to repoRoot, with the same
393	// isolation as testutil.GitGrepGuard. -z keeps non-ASCII paths unquoted, since
394	// GuardGitEnv drops the caller's core.quotePath setting.
395	func productionGoFiles(t *testing.T, repoRoot string) []string {
396		t.Helper()
397	
398		cmd := exec.Command("git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", "*.go") //nolint:noctx // guard test, no cancellation needed
399		cmd.Dir = repoRoot
400		cmd.Env = testutil.GuardGitEnv()
401		out, err := cmd.Output()
402		if err != nil {
403			t.Fatalf("git ls-files: %v", err)
404		}
405		var files []string
406		for name := range strings.SplitSeq(string(out), "\x00") {
407			if name != "" && !strings.HasSuffix(name, "_test.go") {
408				files = append(files, name)
409			}
410		}
411		if len(files) == 0 {
412			t.Fatal("git ls-files found no Go files — the guard's file discovery has gone stale")
413		}
414		return files
415	}
